<?php $s=$billing; $token=$booking['access_token']; $p=$s['active']; if (!$p) foreach ($s['payments'] as $candidate) if ($candidate['status']==='awaiting_upload') { $p=$candidate; break; } ?>
<section class="container billing-page"><a class="outline-link" href="<?= (base_url() . ('booking/detail/'.$token)) ?>"><i class="material-icons" aria-hidden="true">arrow_back</i> รายละเอียดการจอง</a><div class="section-head"><div><span class="eyebrow">PAYMENT</span><h1>ชำระเงิน</h1><p><?= e($booking['reference']) ?> · <?= e($booking['tour_title']) ?></p></div></div>
<?php if ($booking['status']!=='confirmed' || !$s['invoice'] || !$s['remaining']): ?><div class="panel">การจองนี้ยังไม่เปิดชำระเงิน หรือชำระครบแล้ว</div>
<?php elseif ($p && $p['status']==='pending'): ?><div class="panel"><h2>ได้รับสลิปแล้ว รอตรวจสอบ</h2><p>ยอดแจ้งโอน ฿<?= money($p['reported_amount']) ?> · <?= e($p['reference']) ?></p><p>เมื่อทีมงานยืนยัน จะมีใบเสร็จในหน้ารายละเอียดการจอง ไม่ต้องส่งสลิปซ้ำครับ</p><a class="outline-link" target="_blank" rel="noopener" href="<?= (base_url() . ('booking/slip/'.$token.'/'.$p['id'])) ?>">ดูสลิปที่ส่ง <i class="material-icons" aria-hidden="true">north_east</i></a></div>
<?php elseif ($p): $a=json_decode($p['account_snapshot'],true); ?>
<div class="billing-grid"><section class="panel"><span class="eyebrow"><?= $p['kind']==='deposit' ? 'DEPOSIT / มัดจำ' : 'BALANCE / ยอดคงเหลือ' ?></span><h2>ยอดโอน ฿<?= money($p['expected_amount']) ?></h2><p><?= e($p['reference']) ?></p><p>โอนภายใน <?= e($p['expires_at']) ?></p><?php if ($p['expires_at']<date('Y-m-d H:i:s')): ?><div class="notice">รายการหมดเวลาแล้ว อย่าโอนเพิ่ม หากโอนภายในเวลาที่กำหนดไว้ ส่งสลิปให้ทีมงานตรวจสอบได้</div><?php endif ?>
<h3>ชื่อผู้รับเงิน</h3><p><?= e($a['bank_holder'] ?? '') ?></p><?php if (!empty($a['bank_account'])): ?><h3><?= e($a['bank_name'] ?? '') ?></h3><p class="account-number"><?= e($a['bank_account']) ?></p><?php endif ?><?php if (!empty($a['promptpay_number'])): ?><h3>PromptPay</h3><p class="account-number"><?= e($a['promptpay_number']) ?></p><?php endif ?><?php if (!empty($a['payment_qr'])): ?><img class="payment-qr" src="<?= (base_url() . ($a['payment_qr'])) ?>" alt="QR สำหรับชำระเงิน"><p class="fineprint">ตรวจชื่อผู้รับและกรอกยอด ฿<?= money($p['expected_amount']) ?> ในแอปธนาคารก่อนยืนยันโอน</p><?php endif ?>
<form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><button class="text-button" type="submit">ยังไม่ได้โอน · ยกเลิกรายการนี้เพื่อเลือกใหม่</button></form></section>
<section class="panel"><h2>แจ้งชำระเงิน</h2><form method="post" enctype="multipart/form-data" class="stack-form" id="slip-form"><?= csrf_field() ?><input type="hidden" name="action" value="slip"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><label>ยอดที่โอนจริง (บาท)<input type="number" name="reported_amount" min="0.01" max="<?= e(app(\App\Repositories\BillingRepository::class)->decimal($s['remaining'])) ?>" step="0.01" value="<?= e($p['expected_amount']) ?>" required></label><label>วันและเวลาโอน<input type="datetime-local" name="transferred_at" value="<?= date('Y-m-d\TH:i') ?>" required></label><label>ช่องทางโอน<select name="channel" required><?php if (!empty($a['bank_name']) && !empty($a['bank_account'])): ?><option value="bank">บัญชีธนาคาร</option><?php endif ?><?php if (!empty($a['promptpay_number']) || !empty($a['payment_qr'])): ?><option value="promptpay">PromptPay / QR</option><?php endif ?></select></label><label>แนบสลิป<input type="file" name="slip" accept="image/jpeg,image/png" required><small>JPG หรือ PNG ไม่เกิน 5 MB</small></label><button class="btn" type="submit">ส่งสลิปให้ทีมงานตรวจสอบ</button><p class="fineprint">ระบบรับยอดชำระเมื่อทีมงานตรวจสลิปและยืนยันแล้วเท่านั้น</p></form></section></div>
<?php else: ?><section class="panel narrow"><h2>ยอดคงเหลือ ฿<?= money($s['remaining']/100) ?></h2><?php if ($s['due']<date('Y-m-d H:i:s')): ?><p class="notice">พ้นกำหนดชำระ กรุณาติดต่อทีมงานเพื่อขยายเวลา</p><?php else: ?><form method="post" class="stack-form" id="payment-choice"><?= csrf_field() ?><input type="hidden" name="action" value="start"><?php if ($s['deposit_allowed']): ?><label class="payment-choice"><input type="radio" name="kind" value="deposit" checked> ชำระมัดจำ ฿<?= money($s['invoice']['deposit_amount']) ?></label><p class="fineprint">ส่วนที่เหลือ ฿<?= money(($s['remaining']-app(\App\Repositories\BillingRepository::class)->cents($s['invoice']['deposit_amount']))/100) ?> รวมค่าพักเดี่ยว ชำระภายใน <?= e($s['invoice']['balance_due_at']) ?></p><?php else: ?><p>รายการนี้ชำระยอดคงเหลือเต็มจำนวน</p><?php endif ?><label class="payment-choice"><input type="radio" name="kind" value="full" <?= !$s['deposit_allowed'] ? 'checked' : '' ?>> ชำระเต็มยอดคงเหลือ ฿<?= money($s['remaining']/100) ?></label><button class="btn" type="submit">ดูช่องทางชำระเงิน <i class="material-icons" aria-hidden="true">north_east</i></button></form><?php endif ?></section><?php endif ?></section>
